  /** The tool that wrote the inputs, e.g. 'KiCad Pcbnew 10.0.6' (Gerber X2/gbrjob GenerationSoftware). */
  generator?: string | null;
  /** The reader that built this model, e.g. 'boarddd 0.2.0 io.kicad'. */
  reader?: string | null;
  /** When the inputs were made (ISO 8601), if the source says. */
  created?: string | null;
  /** VCS commit of the design (kipr: the head sha). */
  commit?: string | null;
  /** VCS ref or upload/package id the inputs belong to. */
