  /** Material role. */
  kind: "silk" | "paste" | "mask" | "copper" | "dielectric" | "other";
  /** 'inner' for inner copper and dielectrics. */
  side: "top" | "bottom" | "inner" | "none";
  /** mm (with sublayers: their sum). */
